public class LoginCheck {
    public static void main(String[] args) {
        boolean hasAccount = true;
        boolean isVerified = false;
        int age = 20;

        System.out.println(hasAccount && isVerified);          // false
        System.out.println(hasAccount || isVerified);          // true
        System.out.println(hasAccount && !isVerified);         // true
        System.out.println(age >= 18 && hasAccount);           // true
        System.out.println(!(age >= 18 && isVerified));        // true
    }
}

